"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * AREA CHART: several series, stacked, overlapping or as shares
 *
 *   arrive    the first time it's on screen the chart draws
 *             itself from left to right and every figure rolls
 *             up from zero
 *   layout    Stacked, Overlap, 100%: the pill is thrown to the
 *             choice and every band morphs to its new place, the
 *             scale rolling to counts or percentages
 *   toggle    the tiles are the legend: press one and its band
 *             shrinks away while the others settle into the room,
 *             press it again and it grows back. Colours stay with
 *             their series
 *   hover     a thin line follows the pointer with a dot on each
 *             band, and the tiles become the readout: the period
 *             morphs to that week and every figure rolls to it
 *
 * The plot is one tab stop: arrow keys move between points and
 * the readout is announced. The tiles are toggle buttons. Every
 * figure is also in a table for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface AreaSeries {
  id: string;
  label: string;
  /** One value per label. */
  values: number[];
}

export type AreaLayout = "stacked" | "overlap" | "percent";

export interface AreaChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange"
> {
  title?: string;
  /** Under the total, e.g. "orders in the last 12 weeks". */
  caption?: string;
  /** Along the bottom, one per point. */
  labels: string[];
  /** In the readout, e.g. "Week of 28 Sept". Defaults to labels. */
  titles?: string[];
  /** Up to five, in a fixed colour order (--chart-1 to --chart-5). */
  series: AreaSeries[];
  layout?: AreaLayout;
  defaultLayout?: AreaLayout;
  onLayoutChange?: (layout: AreaLayout) => void;
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const PLOT = 200;
const TOP = 10;
const LABELS = 24;
const PAD = 6;
const STEPS = 4;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const COLORS = [
  "var(--chart-1, var(--primary))",
  "var(--chart-2, #e8743b)",
  "var(--chart-3, #1baf7a)",
  "var(--chart-4, #8b6fe8)",
  "var(--chart-5, #e0a21b)",
];
const LAYOUTS: { id: AreaLayout; label: string }[] = [
  { id: "stacked", label: "Stacked" },
  { id: "overlap", label: "Overlap" },
  { id: "percent", label: "100%" },
];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function niceTop(value: number) {
  if (value <= 0) return STEPS;
  const raw = value / STEPS;
  const mag = 10 ** Math.floor(Math.log10(raw));
  const step =
    [1, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10]
      .map((m) => m * mag)
      .find((s) => s >= raw) ?? 10 * mag;
  return step * STEPS;
}

/** A smooth line through the points that never overshoots them (monotone cubic). Works left to right or right to left. */
function monotone(points: [number, number][], move = true) {
  const n = points.length;
  if (!n) return "";
  const r = (v: number) => Math.round(v * 100) / 100;
  const head = `${move ? "M" : "L"}${r(points[0][0])},${r(points[0][1])}`;
  if (n === 1) return head;
  const m: number[] = [];
  for (let i = 0; i < n - 1; i++)
    m.push(
      (points[i + 1][1] - points[i][1]) /
        (points[i + 1][0] - points[i][0] || 1),
    );
  const t: number[] = [m[0]];
  for (let i = 1; i < n - 1; i++)
    t.push(m[i - 1] * m[i] <= 0 ? 0 : (m[i - 1] + m[i]) / 2);
  t.push(m[n - 2]);
  for (let i = 0; i < n - 1; i++) {
    if (m[i] === 0) {
      t[i] = 0;
      t[i + 1] = 0;
      continue;
    }
    const a = t[i] / m[i];
    const b = t[i + 1] / m[i];
    const s = a * a + b * b;
    if (s > 9) {
      const k = 3 / Math.sqrt(s);
      t[i] = k * a * m[i];
      t[i + 1] = k * b * m[i];
    }
  }
  let d = head;
  for (let i = 0; i < n - 1; i++) {
    const [x0, y0] = points[i];
    const [x1, y1] = points[i + 1];
    const dx = (x1 - x0) / 3;
    d += `C${r(x0 + dx)},${r(y0 + t[i] * dx)} ${r(x1 - dx)},${r(y1 - t[i + 1] * dx)} ${r(x1)},${r(y1)}`;
  }
  return d;
}

/** Tweens a list of numbers toward a target, so bands reshape instead of being replaced. */
function useTween(target: number[], reduced: boolean, duration = 620) {
  const [value, setValue] = React.useState(target);
  const from = React.useRef(target);
  const targetRef = React.useRef(target);
  React.useLayoutEffect(() => {
    targetRef.current = target;
  });

  const targetKey = target.join(",");

  React.useEffect(() => {
    from.current = reduced ? target : value;
  });

  React.useEffect(() => {
    if (reduced) return;
    const start = from.current;
    const begin = performance.now();
    let frame = 0;
    const step = (now: number) => {
      const currentTarget = targetRef.current;
      const t = Math.min(1, (now - begin) / duration);
      const e = 1 - Math.pow(1 - t, 4);
      const next = currentTarget.map(
        (v, i) => (start[i] ?? 0) + (v - (start[i] ?? 0)) * e,
      );
      from.current = next;
      setValue(next);
      if (t < 1) frame = requestAnimationFrame(step);
    };
    frame = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame);
  }, [targetKey, reduced, duration]);

  return reduced ? target : value;
}

export function AreaChart({
  title = "Orders",
  caption,
  labels,
  titles,
  series: allSeries,
  layout: layoutProp,
  defaultLayout = "stacked",
  onLayoutChange,
  format,
  locales,
  className = "",
  ...props
}: AreaChartProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const series = allSeries.slice(0, COLORS.length);
  const [ownLayout, setOwnLayout] = React.useState<AreaLayout>(defaultLayout);
  const layout = layoutProp ?? ownLayout;
  const [hidden, setHidden] = React.useState<Set<string>>(() => new Set());
  const [visible, setVisible] = React.useState(false);
  const [plotH, setPlotH] = React.useState(PLOT);
  const [active, setActive] = React.useState<number | null>(null);
  const [keyboard, setKeyboard] = React.useState(false);
  const [width, setWidth] = React.useState(0);
  const [pill, setPill] = React.useState({ left: 0, width: 0, ready: false });
  const rootRef = React.useRef<HTMLDivElement>(null);
  const chartRef = React.useRef<HTMLDivElement>(null);
  const plotRef = React.useRef<HTMLDivElement>(null);
  const chipRefs = React.useRef<(HTMLButtonElement | null)[]>([]);

  const n = labels.length;
  const on = (s: AreaSeries) => !hidden.has(s.id);
  // Each series as a band [lower, upper] at every point, in the layout's units; a hidden series is a band of no height.
  const bands = React.useMemo(() => {
    const shown = series.map((s) =>
      !hidden.has(s.id) ? s.values : s.values.map(() => 0),
    );
    const sums = labels.map((_, i) =>
      shown.reduce((sum, v) => sum + (v[i] ?? 0), 0),
    );
    const result: { lower: number[]; upper: number[] }[] = [];
    let running = labels.map(() => 0);
    for (const values of shown) {
      if (layout === "overlap") {
        result.push({
          lower: labels.map(() => 0),
          upper: labels.map((_, i) => values[i] ?? 0),
        });
      } else {
        const lower = running;
        const upper = labels.map(
          (_, i) =>
            lower[i] +
            (layout === "percent"
              ? sums[i]
                ? (values[i] ?? 0) / sums[i]
                : 0
              : (values[i] ?? 0)),
        );
        running = upper;
        result.push({ lower, upper });
      }
    }
    return result;
  }, [series, labels, layout, hidden]);
  const max =
    layout === "percent"
      ? 1
      : niceTop(Math.max(0, ...bands.flatMap((b) => b.upper)));
  const flat = useTween(
    [max, ...bands.flatMap((b) => [...b.lower, ...b.upper])],
    reduced,
  );
  const drawnMax = flat[0] || 1;
  const drawn = bands.map((_, s) => ({
    lower: flat.slice(1 + s * 2 * n, 1 + s * 2 * n + n),
    upper: flat.slice(1 + s * 2 * n + n, 1 + (s + 1) * 2 * n),
  }));

  // The plot's height is set by the card's width in CSS; read it so the drawing fits.
  React.useLayoutEffect(() => {
    const el = chartRef.current;
    if (!el) return;
    const measure = () =>
      setPlotH((h) => {
        const next = el.offsetHeight - LABELS;
        return next > 0 && next !== h ? next : h;
      });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const el = plotRef.current;
    if (!el) return;
    const measure = () =>
      setWidth((w) => (w === el.offsetWidth ? w : el.offsetWidth));
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const el = chipRefs.current[LAYOUTS.findIndex((l) => l.id === layout)];
    if (!el) return;
    setPill((p) =>
      p.left === el.offsetLeft && p.width === el.offsetWidth
        ? p
        : { left: el.offsetLeft, width: el.offsetWidth, ready: p.width > 0 },
    );
  }, [layout]);

  const x = (i: number) =>
    PAD + (n > 1 ? (i * (width - PAD * 2)) / (n - 1) : (width - PAD * 2) / 2);
  const y = (v: number) => TOP + (plotH - TOP) * (1 - v / drawnMax);

  const choose = (next: AreaLayout) => {
    if (next === layout) return;
    if (layoutProp === undefined) setOwnLayout(next);
    onLayoutChange?.(next);
  };
  const toggle = (sid: string) =>
    setHidden((h) => {
      const next = new Set(h);
      if (next.has(sid)) next.delete(sid);
      // Keep at least one series showing.
      else if (series.filter((s) => !next.has(s.id)).length > 1) next.add(sid);
      return next;
    });
  const pointAt = (clientX: number) => {
    const r = plotRef.current?.getBoundingClientRect();
    if (!r || n < 2) return null;
    return Math.min(
      n - 1,
      Math.max(
        0,
        Math.round(((clientX - r.left - PAD) / (r.width - PAD * 2)) * (n - 1)),
      ),
    );
  };
  const onKeyDown = (e: React.KeyboardEvent) => {
    if (!n) return;
    const from = active ?? n - 1;
    const moves: Record<string, number> = {
      ArrowLeft: from - 1,
      ArrowRight: from + 1,
      Home: 0,
      End: n - 1,
    };
    if (e.key === "Escape") return setActive(null);
    if (!(e.key in moves)) return;
    e.preventDefault();
    setKeyboard(true);
    setActive(
      Math.min(n - 1, Math.max(0, active === null ? from : moves[e.key])),
    );
  };

  const fmt = (v: number) => new Intl.NumberFormat(locales, format).format(v);
  const totalOf = (s: AreaSeries) =>
    active !== null
      ? (s.values[active] ?? 0)
      : s.values.reduce((sum, v) => sum + v, 0);
  const shownTotal = series.filter(on).reduce((sum, s) => sum + totalOf(s), 0);
  const scaleFormat: Intl.NumberFormatOptions =
    layout === "percent"
      ? { style: "percent" }
      : {
          ...format,
          notation: "compact",
          minimumFractionDigits: 0,
          maximumFractionDigits: 1,
        };
  const every = width && n ? Math.max(1, Math.ceil(40 / (width / n))) : 1;
  // Labels thin out on narrow screens; the hovered one always shows, and its close neighbours step aside for it.
  const label = (i: number) =>
    active === i ||
    ((n - 1 - i) % every === 0 &&
      (active === null || every === 1 || Math.abs(i - active) >= every));
  const name = (i: number) => titles?.[i] ?? labels[i];

  return (
    <div
      ref={rootRef}
      className={`@container w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      <div className="p-4 @md:p-5 [--gutter:30px] @md:[--gutter:40px] [--plot:160px] @md:[--plot:200px]">
        {/* The title and its control share a row; the figures sit under both. */}
        <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-2">
          <p className="text-[12px] text-muted-foreground @md:text-[13px]">
            {title}
          </p>
          <div
            role="radiogroup"
            aria-label="Layout"
            className="relative -my-1 inline-flex shrink-0 rounded-full bg-muted p-0.5"
          >
            <span
              aria-hidden="true"
              className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
              style={{
                width: pill.width,
                transform: `translateX(${pill.left}px)`,
                transition:
                  pill.ready && !reduced
                    ? `transform 460ms ${THROW}, width 380ms ${EASE}`
                    : "none",
              }}
            />
            {LAYOUTS.map((l, i) => {
              const selected = l.id === layout;
              return (
                <button
                  key={l.id}
                  ref={(el) => {
                    chipRefs.current[i] = el;
                  }}
                  type="button"
                  role="radio"
                  aria-checked={selected}
                  tabIndex={selected ? 0 : -1}
                  onClick={() => choose(l.id)}
                  onKeyDown={(e) => {
                    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
                    e.preventDefault();
                    const next =
                      (i + (e.key === "ArrowRight" ? 1 : -1) + LAYOUTS.length) %
                      LAYOUTS.length;
                    choose(LAYOUTS[next].id);
                    chipRefs.current[next]?.focus();
                  }}
                  className={`cursor-pointer relative h-6 whitespace-nowrap rounded-full px-2.5 text-[11.5px] font-medium @md:h-7 @md:px-3 @md:text-[12.5px] transition-colors duration-300 ${FOCUS} ${
                    selected
                      ? "text-foreground"
                      : "text-muted-foreground hover:text-foreground"
                  }`}
                >
                  {l.label}
                </button>
              );
            })}
          </div>
        </div>
        <p className="mt-0.5 text-[22px] font-medium leading-tight tracking-[-0.03em] @md:text-[26px] text-foreground">
          <NumberRoll
            value={visible ? shownTotal : 0}
            format={format}
            locales={locales}
            duration={active !== null ? 600 : 1000}
          />
        </p>
        <p className="mt-1 whitespace-nowrap text-[11.5px] text-muted-foreground @md:text-[12.5px]">
          <TextMorph>
            {active !== null ? name(active) : (caption ?? " ")}
          </TextMorph>
        </p>

        <div
          ref={chartRef}
          className="relative mt-4 @md:mt-5"
          style={{ height: `calc(var(--plot) + ${LABELS}px)` }}
        >
          {Array.from({ length: STEPS + 1 }, (_, k) => 1 - k / STEPS).map(
            (f) => (
              <div
                key={f}
                aria-hidden="true"
                className="absolute inset-x-0"
                style={{ top: TOP + (plotH - TOP) * (1 - f) }}
              >
                <span
                  className="absolute left-0 top-0 -translate-y-1/2 text-[10px] leading-none tabular-nums text-muted-foreground/80"
                  style={{
                    width: "calc(var(--gutter) - 8px)",
                    textAlign: "right",
                  }}
                >
                  <NumberRoll
                    value={visible ? max * f : 0}
                    format={scaleFormat}
                    locales={locales}
                    duration={700}
                  />
                </span>
                <div
                  className="border-t border-border"
                  style={{ marginLeft: "var(--gutter)" }}
                />
              </div>
            ),
          )}

          <div
            ref={plotRef}
            role="group"
            tabIndex={0}
            aria-label={`${title}. Use the arrow keys to read each point.`}
            onKeyDown={onKeyDown}
            onBlur={() => keyboard && (setActive(null), setKeyboard(false))}
            onPointerMove={(e) => {
              setKeyboard(false);
              setActive(pointAt(e.clientX));
            }}
            onPointerDown={(e) => setActive(pointAt(e.clientX))}
            onPointerLeave={(e) => e.pointerType === "mouse" && setActive(null)}
            className={`absolute inset-y-0 right-0 touch-pan-y select-none rounded-lg ${FOCUS}`}
            style={{ left: "var(--gutter)" }}
          >
            <div
              className="absolute inset-x-0 top-0"
              style={{
                height: plotH,
                clipPath: visible
                  ? "inset(-8px -8px -8px -8px)"
                  : "inset(-8px 100% -8px -8px)",
                transition: reduced ? "none" : `clip-path 1200ms ${EASE}`,
              }}
            >
              <svg
                aria-hidden="true"
                width={width}
                height={plotH}
                className="absolute inset-0 overflow-visible"
              >
                {width > 0 &&
                  drawn.map((b, s) => {
                    const upper = b.upper.map(
                      (v, i) => [x(i), y(v)] as [number, number],
                    );
                    const lower = b.lower
                      .map((v, i) => [x(i), y(v)] as [number, number])
                      .reverse();
                    const top = monotone(upper);
                    const fill = `${top}${monotone(lower, false)}Z`;
                    const shown = on(series[s]);
                    // Overlap fills lightly so the bands behind still show; stacked bands fill a little more.
                    const wash = layout === "overlap" ? 0.1 : 0.2;
                    return (
                      <g
                        key={series[s].id}
                        style={{
                          opacity: shown ? 1 : 0,
                          transition: reduced
                            ? "none"
                            : `opacity 300ms ${EASE}`,
                        }}
                      >
                        <path d={fill} fill={COLORS[s]} fillOpacity={wash} />
                        <path
                          d={top}
                          fill="none"
                          stroke={COLORS[s]}
                          strokeWidth="2"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                        />
                      </g>
                    );
                  })}
              </svg>
            </div>

            <span
              aria-hidden="true"
              className="pointer-events-none absolute top-0 w-px bg-foreground/20"
              style={{
                height: plotH,
                left: active !== null ? x(active) : 0,
                opacity: active !== null ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `left 260ms ${THROW}, opacity 200ms ${EASE}`,
              }}
            />
            {series.map((s, si) => {
              const showDot = active !== null && on(s);
              const v = drawn[si]?.upper[active ?? n - 1] ?? 0;
              return (
                <span
                  key={s.id}
                  aria-hidden="true"
                  className="pointer-events-none absolute size-2.5 -translate-x-1/2 -translate-y-1/2 rounded-full shadow-[0_0_0_2px_var(--background)]"
                  style={{
                    left: x(active ?? n - 1),
                    top: y(v),
                    background: COLORS[si],
                    opacity: showDot ? 1 : 0,
                    scale: showDot ? "1" : "0.4",
                    transition: reduced
                      ? "none"
                      : `left 260ms ${THROW}, top 260ms ${THROW}, opacity 200ms ${EASE}, scale 260ms ${EASE}`,
                  }}
                />
              );
            })}

            {labels.map((l, i) => (
              <span
                key={l + i}
                aria-hidden="true"
                className={`absolute -translate-x-1/2 whitespace-nowrap text-[11px] leading-none transition-colors duration-200 ${active === i ? "text-foreground" : "text-muted-foreground"}`}
                style={{
                  left: x(i),
                  top: plotH + 9,
                  opacity: label(i) ? 1 : 0,
                }}
              >
                {l}
              </span>
            ))}
          </div>
        </div>

        {/* The tiles: the legend, the switches, and the readout while you point. */}
        {/* The legend as a compact strip: each series is a toggle with its figure and share. */}
        <div
          className="mt-4 grid gap-x-1 border-t border-border pt-2.5 @md:mt-5 @md:pt-3"
          style={{
            gridTemplateColumns: `repeat(${Math.min(series.length, 3)}, minmax(0, 1fr))`,
          }}
        >
          {series.map((s, si) => {
            const shown = on(s);
            const value = totalOf(s);
            const share = shownTotal ? value / shownTotal : 0;
            return (
              <button
                key={s.id}
                type="button"
                aria-pressed={shown}
                onClick={() => toggle(s.id)}
                className={`cursor-pointer -mx-1.5 flex min-w-0 flex-col items-start rounded-lg px-1.5 py-1 text-left transition-[opacity,background-color] duration-300 hover:bg-accent ${FOCUS} ${
                  shown ? "" : "opacity-45"
                }`}
              >
                <span className="flex max-w-full items-center gap-1.5 text-[11px] text-muted-foreground @md:text-[11.5px]">
                  <span
                    aria-hidden="true"
                    className="size-[7px] shrink-0 rounded-full transition-[background-color,box-shadow] duration-300"
                    style={{
                      background: shown ? COLORS[si] : "transparent",
                      boxShadow: `inset 0 0 0 1.5px ${COLORS[si]}`,
                    }}
                  />
                  <span className="truncate">{s.label}</span>
                </span>
                <span className="mt-0.5 flex items-baseline gap-1">
                  <span className="text-[13.5px] font-medium tracking-[-0.01em] text-foreground @md:text-[14.5px]">
                    <NumberRoll
                      value={visible && shown ? value : 0}
                      format={format}
                      locales={locales}
                      duration={600}
                    />
                  </span>
                  <span className="text-[10.5px] text-muted-foreground @md:text-[11px]">
                    <NumberRoll
                      value={visible && shown ? share : 0}
                      format={{ style: "percent" }}
                      duration={600}
                    />
                  </span>
                </span>
              </button>
            );
          })}
        </div>

        <p aria-live="polite" className="sr-only">
          {keyboard && active !== null
            ? `${name(active)}: ${series
                .filter(on)
                .map((s) => `${s.label} ${fmt(s.values[active] ?? 0)}`)
                .join(", ")}`
            : ""}
        </p>
        <table className="sr-only">
          <caption>
            {title}
            {caption ? `, ${caption}` : ""}
          </caption>
          <thead>
            <tr>
              <th scope="col">Point</th>
              {series.map((s) => (
                <th key={s.id} scope="col">
                  {s.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {labels.map((l, i) => (
              <tr key={l + i} id={`${id}-${i}`}>
                <th scope="row">{name(i)}</th>
                {series.map((s) => (
                  <td key={s.id}>{fmt(s.values[i] ?? 0)}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

